#[test]
fn reverse_golden_desktop_frame() {
    let frame = decode_frame("go_desktop_frame.bin");
    match frame {
        Frame::Desktop(f) => {
            assert_eq!(f.sequence, 42);
            assert_eq!(f.x, 10);
            assert_eq!(f.y, 20);
            assert_eq!(f.width, 1920);
            assert_eq!(f.height, 1080);
            assert_eq!(f.encoding, FrameEncoding::Zstd);
            assert_eq!(f.data, vec![0xDE, 0xAD, 0xBE, 0xEF]);
        }
        other => panic!("expected Desktop, got {:?}", other),
    }
}
